// Раскладка клавиатуры УК-НЦ (МС7007) для клавиатуры хоста.
//
// Слева клавиша хоста, справа НОМЕР клавиши машины - тот же, что в
// uknc.keys, где он привязан к рисунку. Контроллер отдаёт номер клавиши, а
// не код символа; разряд 7 регистра 177702 означает отпускание, а в символы
// всё переводит ПЗУ машины. Поэтому модификаторов вида /S здесь нет: РУС и
// регистр - забота самой машины, и `use_remap = 0` у устройства.
//
// Отсюда же правило для верхнего регистра: знак, который на машине набирают
// с НР, отдан тому же номеру, что и его нижний сосед. Shift хоста приходит
// отдельной клавишей и сам прижимает НР, так что `!` на хосте - это НР плюс
// номер клавиши `1`, и машина получает именно то, что нарисовано на её
// собственной клавише.
//
// Номера сняты с ПЗУ машины, вывод - в заголовке uknc.keys.
//
// Числа восьмеричные: у машины radix = 8.

// --- Буквы ------------------------------------------------------------
// Клавиша хоста отдана клавише машины с той же ЛАТИНСКОЙ надписью, поэтому
// в латинском регистре хост печатает то, что на нём написано, а в русском
// получается ЯВЕРТЫ - как и на самой машине.
A:              &72     // А
B:              &76     // Б
C:              &50     // Ц
D:              &57     // Д
E:              &33     // Е
F:              &47     // Ф
G:              &55     // Г
H:              &156    // Х
I:              &73     // И
J:              &27     // Й
K:              &52     // К
L:              &56     // Л
M:              &112    // М
N:              &54     // Н
O:              &75     // О
P:              &53     // П
Q:              &67     // Я
R:              &74     // Р
S:              &111    // С
T:              &114    // Т
U:              &51     // У
V:              &137    // Ж
W:              &71     // В
X:              &115    // Ь
Y:              &70     // Ы
Z:              &157    // З

// --- Цифровой ряд и его верхний регистр -------------------------------
1:              &30
2:              &31
3:              &32
4:              &13
5:              &34
6:              &35
7:              &16
8:              &17
9:              &177
0:              &176
!:              &30
":              &31
#:              &32
$:              &13
%:              &34
&:              &35
':              &16
(:              &17
):              &177

// --- Знаки ------------------------------------------------------------
semicolon:      &7      // ; +
plus:           &7
colon:          &174    // : *
*:              &174
,:              &117    // , <
<:              &117
.:              &135    // . >
>:              &135
slash:          &173    // / ?
?:              &173
minus:          &175    // - =
=:              &175
[:              &36     // Ш [
{:              &36
]:              &37     // Щ ]
}:              &37
\:              &136    // Э \
bar:            &136
circum:         &110    // Ч ^
under:          &155    // Ъ _
@:              &77     // Ю @

// --- Управляющие ------------------------------------------------------
space:          &113
tab:            &26
esc:            &6      // АР2
ret:            &153    // ВК
enter:          &166    // ВВОД цифрового блока
back:           &132    // ЗБ
del:            &132
left:           &116
right:          &133
up:             &154
down:           &134

// --- Регистровые ------------------------------------------------------
shift:          &105    // НР
ctrl:           &46     // УПР
alt:            &66     // ГРАФ
caps:           &107    // ФИКС

// --- Функциональные ---------------------------------------------------
f1:             &10     // К1
f2:             &11     // К2
f3:             &12     // К3
f4:             &14     // К4
f5:             &15     // К5
f6:             &106    // АЛФ, пока нажата - другой алфавит
f7:             &172    // ПОМ
f8:             &151    // ИСП
f9:             &152    // УСТ
f10:            &171    // СБРОС, очистка экрана
f12:            &4      // СТОП, ставит HALT центральному процессору
